export interface Company {
  id: number;
  nombreComercial: string;
  razonSocial: string;
  tipoIdentificacion: '01' | '02' | '03' | '04'; // 01: Física, 02: Jurídica, etc.
  identificacion: string;
  correoEmisor: string;
  ivaPorDefecto: number;
  colorPrimario: string;
  colorSidebar: string;
  logoUrl: string;
  actividadEconomica: string;
  perfilCompania: 'Fisioterapia' | 'Nutrición' | 'Ambas';
}

export interface User {
  id: number;
  idCompania: number;
  nombre: string;
  usuario: string;
  correo: string;
  contrasena: string;
  rol: 'Administrador' | 'Profesional';
}

export interface Patient {
  id: number;
  idCompania: number;
  nombreCompleto: string;
  fechaNacimiento: string;
  edad: number;
  ocupacion: string;
  correoElectronico: string;
  situacionVivienda: 'SOLO' | 'ACOMPAÑADO' | 'FAMILIAR';
  tipoIdentificacion: '01' | '02' | '03' | '04' | 'EXT';
  identificacion: string;
  telefono: string;
  provinciaId: number;
  cantonId: number;
  distritoId: number;
  otrasSenas: string;
  // Antecedentes nutricionales
  diabetes: boolean;
  hipertension: boolean;
  gastritis: boolean;
  estrenimiento: boolean;
  alergiasAlimentarias: string;
  // Antecedentes fisioterapia
  fracturas: string;
  esguinces: string;

export interface Cita {
  id: number;
  idCompania: number;
  idPaciente: number;
  idUsuarioNutricionista: number; // Profesional a cargo
  idConsulta?: number | null; // Se llena cuando se inicia la consulta
  fechaHora: string; // Formato "YYYY-MM-DDTHH:MM"
  duracionMinutos: number;
  estadoCita: 'PROGRAMADA' | 'CONFIRMADA' | 'CANCELADA' | 'COMPLETADA' | 'NO_ASISTIO';
  notas: string;
  confirmacionEnviadaEn?: string | null;
  recordatorioEnviadoEn?: string | null;
  cancelacionEnviadaEn?: string | null;
}

export interface CompaniaSmtpConfig {
  id: number;
  idCompania: number;
  proveedor: 'GMAIL' | 'OUTLOOK' | 'OTRO';
  smtpHost: string;
  smtpPort: number;
  smtpSeguridad: 'TLS' | 'SSL' | 'NINGUNA';
  smtpUsuario: string;
  smtpPasswordCifrado: string;
  remitenteNombre: string;
  remitenteCorreo: string;
  recordatorioHorasAntes: number;
  activo: boolean;
}

export interface NotificationLog {
  id: number;
  idCompania: number;
  idCita: number;
  tipo: 'CONFIRMACION' | 'MODIFICACION' | 'RECORDATORIO' | 'CANCELACION';
  destinatario: string;
  asunto: string;
  cuerpo: string;
  enviadoEn: string;
}

export interface Consultation {
  id: number;
  idPaciente: number;
  idCompania: number;
  fecha: string;
  tipo: 'Nutrición' | 'Fisioterapia';
  motivo: string;
  horasSueno: number;
  compromiso: number; // 1-10

  // Nutrición específica
  antropometria?: {
    peso: number; // kg
    talla: number; // cm
    imc: number;
    grasaCorporal: number; // %
    grasaVisceral: number; // nivel
    masaMuscular: number; // kg
    masaOsea: number; // kg
    cintura: number; // cm
    abdominal: number; // cm
  };
  dieta?: {
    totalCalorias: number;
    desayuno: string;
